typedef unsigned int nslSoundId;
#define GAS_MAX_INSTANCES 48
#define GAS_RPC_COMMAND_LIST 0x100f
#define NSL_GET_SLOT_FROM_ID(x) (x&0x3ff)
#define NULL 0
struct GasCommandEntry { unsigned instance_id; short set_volume:1; short set_paused:1; short set_pitch:1; short paused:1; short unused:12; short pitch; short volume_right; short volume_left; };
template<class T> class fifo_queue { T *queue; short queue_max,start,end,count; public: short push(const T&); T pop(); int size(){return count;} };
struct nslSound { int isReady,used,inRange,isReallyReady,isPlaying,isReallyPlaying,looping,isQueuing; short left,right,old_left,old_right; unsigned gasInstanceId; int pauseCount,dampenCount; unsigned myId,mySource,myEmitter; float rawVolume,positionalVolume,angle,pitch,minDist,maxDist; };
struct nslEmitter;
struct nslSystem { char pad[0x4040]; nslSound soundSlots[256]; unsigned sourceSlotsUsedCount,soundSlotsUsedCount,emitterSlotsUsedCount; int firstInit,initialized; unsigned numBanks; fifo_queue<nslSoundId> queuedSounds; int speakerMode,outputMode,language,cdDvdMode; unsigned long long lastClock; bool on; };
extern nslSystem nsl; asm(".equ nsl,0x004935f0");
extern void nslFatal(const char *, ...); extern int _nslAssembleCommandListAndCheck3dSounds(nslSound *, void *); extern int _nslCheckAutoReleaseEmitters(nslEmitter *, void *); extern int _nslSoundForEach(int (*)(nslSound *, void *), void *); extern int _nslEmitterForEach(int (*)(nslEmitter *, void *), void *); extern int nslPs2GasRpc(int,const char *,int,int,int,int); extern void nslPlaySound(nslSoundId);
asm(".equ nslFatal__FPCce,0x00391420"); asm(".equ _nslAssembleCommandListAndCheck3dSounds__FP8nslSoundPv,0x00390270"); asm(".equ _nslCheckAutoReleaseEmitters__FP10nslEmitterPv,0x00390228"); asm(".equ _nslSoundForEach__FPFP8nslSoundPv_iPv,0x00390d20"); asm(".equ _nslEmitterForEach__FPFP10nslEmitterPv_iPv,0x00390c98"); asm(".equ nslPs2GasRpc__FiPCciiii,0x00391ac0"); asm(".equ nslPlaySound__FUi,0x0038cb20"); asm(".equ pop__t10fifo_queue1ZUi,0x0038f040"); asm(".equ push__t10fifo_queue1ZUiRCUi,0x0038efd0");
#define ASSERT_NSL_INITIALIZED() do { if (!(nsl.initialized == 1)) nslFatal("NSL NOT INITIALIZED"); } while(0)
void nslFrameAdvance( float timeElapsed )
{ 
  if (!nsl.initialized) return;
  if (!nsl.on) return;
  ASSERT_NSL_INITIALIZED();

  // Things we need to do... 
  // *Update volumes for changed listener positions &
  //  Set volumes on sounds based on changes in the
  //  sfx/music/ambient/voice volumes   - CHECK
  // *Set pitches ? 
  // *auto release emitters

  GasCommandEntry commandList[GAS_MAX_INSTANCES];  
  for (int i=0; i < GAS_MAX_INSTANCES; i++)
  {
    commandList[i].set_volume = 0;
    commandList[i].set_paused = 0;
    commandList[i].set_pitch  = 0;
    commandList[i].instance_id = (unsigned int)-1;
    commandList[i].pitch          = 0x5AFE;
    commandList[i].volume_left    = 0x5AFE;
    commandList[i].volume_right   = 0x5AFE;
  }

  _nslSoundForEach(_nslAssembleCommandListAndCheck3dSounds, commandList);


  // Send off all the volume and pause adjustments
  nslPs2GasRpc(GAS_RPC_COMMAND_LIST, (char *)commandList, 0, 0, 0, 0);

  // Now we check the queued sounds to see if they 
  // are ready to be played
  int size = nsl.queuedSounds.size();
  for (int k=0; k < size; k++) 
  {
    // Grab the first queued sound
    nslSoundId s = nsl.queuedSounds.pop();
    // Is it still valid
    if (nsl.soundSlots[NSL_GET_SLOT_FROM_ID(s)].used) 
    {
      // is it ready
      if (nsl.soundSlots[NSL_GET_SLOT_FROM_ID(s)].isReallyReady)
      {
        // Is it paused
        if (nsl.soundSlots[NSL_GET_SLOT_FROM_ID(s)].pauseCount < 1)
          nslPlaySound(s);     
        else // paused, put it back
        {
#ifdef DEBUG_OUTPUT
    nslSound *snd = &nsl.soundSlots[NSL_GET_SLOT_FROM_ID(s)];
    nslPrintf("PUSHING %s back 'cause it's paused\n", nsl.sourceSlots[NSL_GET_SLOT_FROM_ID(snd->mySource)].fileName);
#endif
           nsl.queuedSounds.push(s);
        }
      }  
      else // not ready, put it back
      {
#ifdef DEBUG_OUTPUT
    nslSound *snd = &nsl.soundSlots[NSL_GET_SLOT_FROM_ID(s)];
    nslPrintf("PUSHING %s for the nth time (not ready)\n", nsl.sourceSlots[NSL_GET_SLOT_FROM_ID(snd->mySource)].fileName);
#endif
        nsl.queuedSounds.push(s);
      }
    }
  }

  _nslEmitterForEach(_nslCheckAutoReleaseEmitters, NULL);

  // DONE!
}
